    static void Metadata()
    {
        const string A="E043 P42-P44/P50; R16 finite metadata index and invariant presentation ENGINEERING";
        Add("M/all-text",A,()=>{var a=Chart(text:Text(metadata:"Title:ASCII title\nTitleUnicode:標題\nArtist:ASCII artist\nArtistUnicode:ศิลปิน\nCreator:Author\nVersion:Expert\nBeatmapID:411\nBeatmapSetID:72",general:"Mode:0\nAudioFilename:song.wav"));var m=a.Metadata!;Eq(m.Title,"ASCII title");Eq(m.Artist,"ASCII artist");Eq(m.Creator,"Author");Eq(m.Version,"Expert");Eq(m.ChartId,411);Eq(m.SetId,72);Eq(m.AudioFilename,"song.wav");});
        foreach(bool unicode in new[]{false,true}) Add("M/unicode-preference-"+unicode,A,()=>{var a=LocalChartCatalog.Index(Put(text:Text(metadata:"Title:Plain\nTitleUnicode:標題\nArtist:PlainArtist\nArtistUnicode:ศิลปิน")),unicode);Eq(a.Metadata!.Title,unicode?"標題":"Plain");Eq(a.Metadata.Artist,unicode?"ศิลปิน":"PlainArtist");});
        Add("M/unicode-empty-fallback",A,()=>{var a=LocalChartCatalog.Index(Put(text:Text(metadata:"Title:Plain\nTitleUnicode: \nArtist:PlainArtist\nArtistUnicode:")),true);Eq(a.Metadata!.Title,"Plain");Eq(a.Metadata.Artist,"PlainArtist");});
        Add("M/missing-title-filename",A,()=>{var a=Chart("song/my-difficulty.osu",Text(metadata:""));Eq(a.Metadata!.Title,"my-difficulty");Eq(a.Metadata.Artist,null);Eq(a.Metadata.Creator,null);Eq(a.Metadata.Version,null);Yes(a.Label.StartsWith("my-difficulty.osu"),"filename row fallback");});
        Add("M/scalars",A,()=>{var a=Chart(text:Text(difficulty:"HPDrainRate:3.25\nCircleSize:4.5\nOverallDifficulty:6.75\nApproachRate:8.125"));var m=a.Metadata!;Eq(m.Hp,3.25f);Eq(m.Cs,4.5f);Eq(m.Od,6.75f);Eq(m.Ar,8.125f);});
        foreach(string value in new[]{"invalid","NaN","Infinity","-Infinity"})Add("M/nonfinite-scalar-"+value,A,()=>{var a=Chart(text:Text(difficulty:"HPDrainRate:"+value+"\nCircleSize:"+value+"\nOverallDifficulty:"+value+"\nApproachRate:"+value));Eq(a.Metadata!.Hp,null);Eq(a.Metadata.Cs,null);Eq(a.Metadata.Od,null);Eq(a.Metadata.Ar,null);Yes(a.Metadata.Details.Contains("HP:? CS:? OD:? AR:?"),"bounded missing scalars");});
        Add("M/counts-and-stored-end",A,()=>{var a=Chart(text:Text(rows:"10,20,1000,1,0\n20,30,2000,8,0,77000\n40,50,3000,1,0"));var m=a.Metadata!;Eq(m.Objects,3);Eq(m.Circles,2);Eq(m.Spinners,1);Eq(m.Sliders,0);Eq(m.DurationMilliseconds,77000);Yes(m.Details.Contains("1:17"),"stored maximum endpoint");});
        Add("M/slider-duration-unavailable",A,()=>{var a=Chart(text:Text(rows:"50,60,2000,2,0,L|250:60,1,200"));Eq(a.Metadata!.Sliders,1);Eq(a.Metadata.DurationMilliseconds,null);Yes(a.Metadata.Details.Contains("until slider preparation"),"not fabricated span duration");});
        Add("M/base-bpm-filter",A,()=>{var a=Chart(text:Text(timing:"0,600,4,1,1,50,1,0\n1000,-50,4,1,1,50,0,0\n2000,300,4,1,1,50,1,0\n3000,150,4,1,1,50,0,0"));Eq(a.Metadata!.MinimumBpm,100d);Eq(a.Metadata.MaximumBpm,200d);});
        foreach(string timing in new[]{"","0,0,4,1,1,50,1,0","0,NaN,4,1,1,50,1,0","0,Infinity,4,1,1,50,1,0"}) Add("M/no-bpm-"+(timing.Length==0?"empty":timing.Split(',')[1]),A,()=>{var a=Chart(text:Text(timing:timing));Eq(a.Metadata!.MinimumBpm,null);Eq(a.Metadata.MaximumBpm,null);});
        Add("M/invariant-details",A,()=>{var a=Chart(text:Text(difficulty:"HPDrainRate:3.25\nCircleSize:4.5\nOverallDifficulty:6.75\nApproachRate:8.125"));var old=CultureInfo.CurrentCulture;try{CultureInfo.CurrentCulture=CultureInfo.GetCultureInfo("fr-FR");Yes(a.Metadata!.Details.Contains("HP:3.25 CS:4.5 OD:6.75 AR:8.13"),"explicit invariant scalar formatting");}finally{CultureInfo.CurrentCulture=old;}});
        Add("M/changed-display-same-path",A,()=>{string p=Put();var a=LocalChartCatalog.Index(p);File.WriteAllText(p,Text(metadata:"Title:Replacement\nArtist:Other\nVersion:Hard"));var b=LocalChartCatalog.Index(p);Eq(b.Metadata!.Title,"Replacement");Eq(a.Metadata!.Title,"Independent QA14");Different(a,b);});
        Add("M/no-gameplay-side-effects",A,()=>{var a=Chart();var map=a.LoadGameplay();var s=Ohno.CircleGame.Gameplay.CircleSession.CreateFreshOrdinary(map,Ohno.CircleGame.Gameplay.ScoreConfiguration.FromBeatmap(map));int events=s.Ledger.EventCount;double hp=s.Health!.State.H;var k=s.Scoring.K;for(int i=0;i<4;i++){_ = LocalChartCatalog.Index(a.Path);_ = a.Metadata!.Details;_ = StarDisplay.Prepare(a,0,0);}Eq(s.Ledger.EventCount,events);Eq(s.Health.State.H,hp);Eq(s.Scoring.K,k);Eq(map.Circles[0].StartTime,1700);});
        Add("M/settings-default",A,()=>{var s=SelectionSettings.Read(Path.Combine(work,"missing.json"));Eq(s.BeatmapDirectory,"Songs");Eq(s.PreferUnicode,false);Eq(s.SongsRoot(work),Path.Combine(work,"Songs"));Eq(SelectionSettings.ConfigurationPath(work),Path.Combine(work,"selection.json"));});
        Add("M/settings-explicit",A,()=>{string p=Path.Combine(work,"selection.json");File.WriteAllText(p,"{\"BeatmapDirectory\":\"Charts\",\"PreferUnicode\":true}");var s=SelectionSettings.Read(p);Eq(s.SongsRoot(work),Path.Combine(work,"Charts"));Eq(s.PreferUnicode,true);});
        foreach(string data in new[]{"null","{","{\"BeatmapDirectory\":\" \"}"})Add("M/settings-invalid-"+data.Length,A,()=>{string p=Path.Combine(work,"selection.json");File.WriteAllText(p,data);if(data=="{")Throws<JsonException>(()=>SelectionSettings.Read(p));else Throws<InvalidDataException>(()=>SelectionSettings.Read(p));});
        foreach(int bytes in new[]{16383,16384,16385})Add("M/settings-limit-"+bytes,A,()=>{string p=Path.Combine(work,"selection.json");File.WriteAllText(p,"{}"+new string(' ',bytes-2));if(bytes<=16384)Eq(SelectionSettings.Read(p).BeatmapDirectory,"Songs");else Throws<InvalidDataException>(()=>SelectionSettings.Read(p));});
    }
    static void Stars()
    {
        const string A="E043 M1bc7/M1bd5/M1bdb/M2d7f/P51-P57; R16 supplied-cache admission ENGINEERING, no calculator";
        SuppliedStar Supply(CatalogChart c,float value=4.25f,string compatibility="osu-stable:E043:cache-v1",string source="Independent finite cache operand",string? hash=null,int mode=0,int mods=0,bool stale=false)=>new(compatibility,source,hash??c.Fingerprint!.Sha256,mode,mods,value,stale);
        Add("T/no-cache",A,()=>{var a=Chart();var d=StarDisplay.Prepare(a,0,0);Eq(d.State,"missing");Eq(d.Text,"Stars not calculated · no compatible cache");});
        Add("T/compatible",A,()=>{var a=Chart();var d=StarDisplay.Prepare(a,0,0,Supply(a));Eq(d.State,"valid");Eq(d.Text,"4.25★ · supplied cache · Independent finite cache operand");});
        Add("T/null-source",A,()=>{var a=Chart();Eq(StarDisplay.Prepare(a,0,0,Supply(a,source:null!)).State,"unsupported");});
        foreach(string source in new[]{""," ","\t"})Add("T/missing-source-"+source.Length+"-"+(source.Length>0?(int)source[0]:0),A,()=>{var a=Chart();Eq(StarDisplay.Prepare(a,0,0,Supply(a,source:source)).State,"unsupported");});
        foreach(string tag in new[]{"other","osu-stable:E043:cache-v2"})Add("T/wrong-compatibility-"+tag,A,()=>{var a=Chart();Eq(StarDisplay.Prepare(a,0,0,Supply(a,compatibility:tag)).State,"unsupported");});
        Add("T/hash-mismatch",A,()=>{var a=Chart();var d=StarDisplay.Prepare(a,0,0,Supply(a,hash:new string('0',64)));Eq(d.State,"stale");Yes(!d.Text.Contains('★'),"no value attributed to changed chart");});
        Add("T/changed-chart-cache",A,()=>{string p=Put();var old=LocalChartCatalog.Index(p);var cache=Supply(old);File.AppendAllText(p,"\n// revision");var next=LocalChartCatalog.Index(p);Eq(StarDisplay.Prepare(next,0,0,cache).State,"stale");});
        foreach((int requested,int supplied) in new[]{(1,1),(0,1),(2,0)})Add($"T/mode-{requested}-{supplied}",A,()=>{var a=Chart();Eq(StarDisplay.Prepare(a,requested,0,Supply(a,mode:supplied)).State,"mismatched");});
        foreach((int raw,int key,bool valid) in new[]{(0,0,true),(1,0,true),(8,8,true),(1371,1370,true),(8,0,false),(0,8,false),(1,1,false)})Add($"T/mods-{raw}-{key}",A,()=>{var a=Chart();Eq(StarDisplay.Prepare(a,0,raw,Supply(a,mods:key)).State,valid?"valid":"mismatched");});
        foreach((string name,float value,string text,bool stale) in new[]{("zero",0f,"0",false),("ordinary",4.56789f,"4.56",false),("below-decimal",1.15f,"1.14",false),("one-cent",1.01f,"1",false),("two675",2.675f,"2.67",false),("negative",-4.5f,"4.5",true),("negative-boundary",-1.15f,"1.14",true),("explicit-stale",4.25f,"4.25",true)})
            Add("T/value-"+name,A,()=>{var a=Chart();var d=StarDisplay.Prepare(a,0,0,Supply(a,value,stale:name=="explicit-stale"));Eq(d.State,stale?"stale":"valid");Eq(d.Text,text+"★ · "+(stale?"stale supplied cache":"supplied cache")+" · Independent finite cache operand");observations.Add(new{inputBits=Convert.ToHexString(BitConverter.GetBytes(value)),binary32AsDouble=(double)value});});
        foreach((string name,float value) in new[]{("nan",float.NaN),("positive-infinity",float.PositiveInfinity),("negative-infinity",float.NegativeInfinity)})Add("T/"+name,A,()=>{var a=Chart();var d=StarDisplay.Prepare(a,0,0,Supply(a,value));Eq(d.State,"unsupported");Eq(d.Text,"Star value unavailable");observations.Add(new{inputBits=Convert.ToHexString(BitConverter.GetBytes(value))});});
        Add("T/invariant-format",A,()=>{var a=Chart();var old=CultureInfo.CurrentCulture;try{CultureInfo.CurrentCulture=CultureInfo.GetCultureInfo("fr-FR");Eq(StarDisplay.Prepare(a,0,0,Supply(a,4.25f)).Text,"4.25★ · supplied cache · Independent finite cache operand");}finally{CultureInfo.CurrentCulture=old;}});
        Add("T/tag-not-calculator-certification",A,()=>{var a=Chart();var input=Supply(a,123.25f,source:"Artificial operand, no calculator claim");Eq(StarDisplay.Prepare(a,0,0,input).Text,"123.25★ · supplied cache · Artificial operand, no calculator claim");Eq(a.GameplayValidated,false);observations.Add(new{classification="ENGINEERING supplied-value contract only; no original M08d9 producer verification"});});
    }
